import{_ as a,a0 as l,w as s,s as g,ao as r,I as n,x as o,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"怎样在Github上托管开源代码库 | LCTT x X-CMD","titleTemplate":false,"description":"怎样在Github上托管开源代码库 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在Github上托管开源代码库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在Github上托管开源代码库 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 How to Host Open Source Code Repository in github","title":"怎样在Github上托管开源代码库","tag":"201505","desc":""},"relativePath":"201505/20150324 How to Host Open Source Code Repository in github.md","filePath":"[post].md"}'),d={name:"201505/20150324 How to Host Open Source Code Repository in github.md"};function u(h,t,m,b,c,x){const e=l("Link");return s(),g("div",null,[t[16]||(t[16]=r('<h1 id="怎样在github上托管开源代码库" tabindex="-1">怎样在Github上托管开源代码库 <a class="header-anchor" href="#怎样在github上托管开源代码库" aria-label="Permalink to “怎样在Github上托管开源代码库”">​</a></h1><p>大家好，今天我们要学习一下怎样在github.com提供的仓库中托管开源软件源代码。GitHub是一个基于web的Git仓库托管服务，提供基于 git 的分布式版本控制和源代码管理(SCM)功能，并加入了自身的特点。它给开源项目和私有项目提供了一个互相协作的工作区、代码预览和代码管理功能。不像Git是一个完完全全的命令行工具，GitHub提供了一个基于web的图形化界面和桌面，也整合了手机操作。GitHub同时提供了私有库付费计划和通常用来管理开源软件项目的免费账号。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/github-universe.jpg" alt="github universe logo"></p><p>这是一种快速灵活，基于web的托管服务，它使用方便，管理分布式版本控制系统也是相当容易，任何人都能将他们的软件源代码托管到 github，让全球各地数以百万计的人可以使用它、参与贡献、共享它、进行问题跟踪以及更多的用途。这里有一些简单快速地托管软件源代码的方法。</p><h3 id="_1-创建一个新的github账号" tabindex="-1">1. 创建一个新的Github账号 <a class="header-anchor" href="#_1-创建一个新的github账号" aria-label="Permalink to “1. 创建一个新的Github账号”">​</a></h3>',5)),n("p",null,[t[1]||(t[1]=o("首先，打开你最喜欢的浏览器并访问",-1)),i(e,{href:"http://github.com/"},{default:p(()=>[...t[0]||(t[0]=[o("github",-1)])]),_:1}),t[2]||(t[2]=o("，首页页面如下所示。",-1))]),t[17]||(t[17]=r(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/github-homepage.png" alt="Github Homepage"></p><p>现在，首页打开之后，请填写一个新的github账号用于注册。</p><p>输入注册所需的有效信息之后，你会被转到计划选择的步骤。在这个页面上有5种计划，我们可以根据需要来选择，这里我们要选择免费计划。所以，我们点击选择Free计划并完成注册。如果我们接下去还打算创建一个组织，那我们需要勾选“Help me setup an organization next”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/choosing-plan.png" alt="choosing plan"></p><h3 id="_2-创建一个新的库" tabindex="-1">2. 创建一个新的库 <a class="header-anchor" href="#_2-创建一个新的库" aria-label="Permalink to “2. 创建一个新的库”">​</a></h3><p>成功注册新账号或登录上Github之后，我们需要创建一个新的库来开始我们的征程。</p><p>点击位于顶部靠右账号id旁边的<strong>(+)</strong>按钮，然后点击“New Repository”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/create-new-repository.png" alt="Add new repository"></p><p>点击创建一个新的库之后，我们进入了填写所需信息的页面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/adding-information-repository.png" alt="adding repository information"></p><p>填写好信息之后，我们点击绿色的“Create repository”按钮。</p><p>这些步骤都做完之后，我们将看到类似于下面这张图的页面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/repository-github.png" alt="repository github"></p><h3 id="_3-上传一个已有项目" tabindex="-1">3. 上传一个已有项目 <a class="header-anchor" href="#_3-上传一个已有项目" aria-label="Permalink to “3. 上传一个已有项目”">​</a></h3><p>如果我们想在Github上分享我们的项目，我们自然要把代码推上我们创建的库中。想要这样的话，我们首先要在我们的Linux机器上安装git。如果我在机器上运行的是Ubuntu 14.04 LTS，我需要运行<strong>apt</strong>工具来安装它。</p><pre><code>$ sudo apt-get install git
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/install-git.png" alt="installing git"></p><p>现在git已经准备就绪，我们要上传代码了。</p><p><strong>注意</strong>：为了避免错误，不要在初始化的新库中包含<strong>README</strong>、license或gitignore等文件，你可以在项目推送到Github上之后再添加它们。</p><p>在终端上，我们需要切换当前工作目录为你的本地项目的目录，然后将其初始化为Git库。</p><pre><code>$ git init
</code></pre><p>接着我们添加新的本地库里中的文件，作为我们的首次提交内容。</p><pre><code>$ git add .
</code></pre><p>现在我们就提交我们在本地库所添加的文件。</p><pre><code>$ git commit -m &#39;First commit&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/git-commit.png" alt="git commit"></p><p>在终端上，添加远程库的URL地址，以便我们的本地库推送到远程。</p><pre><code>$ git remote add origin 远程库的URL
$ git remote -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/adding-remote-url.png" alt="adding remote url"></p><p>注意：请确保将上述“远程库的URL”替换成了你自己的远程库的URL。</p><p>现在，要将我们的本地库的改变推送至GitHub的版本库中，我们需要运行以下命令，并且输入所需的用户名和密码。</p><pre><code>$ git push origin master
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pushing-repo.png" alt="pushing repo"></p><h3 id="克隆一个库" tabindex="-1">克隆一个库 <a class="header-anchor" href="#克隆一个库" aria-label="Permalink to “克隆一个库”">​</a></h3><p>如果我们想用一条简单地命令从github上下载代码库至本机上，我们可以用git clone命令，该命令将会从远程库中克隆最新的目录。</p><pre><code>$ git clone https://github.com/aruntechgeek/linspeed.git
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/cloning-repo.png" alt="cloning repo"></p><p>请把以上这条URL地址更改成你想要克隆的地址。</p><h3 id="推送改动" tabindex="-1">推送改动 <a class="header-anchor" href="#推送改动" aria-label="Permalink to “推送改动”">​</a></h3><p>如果我们对我们的代码做了更改并想把它们推送至我们的远程库中，我们应该在该目录下运行以下命令。</p><pre><code>$ git add .
$ git commit -m &quot;Updating&quot;
$ git push
</code></pre><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>啊哈！我们已经成功地将我们的项目源代码托管到Github的库中了。Github是快速灵活的基于web的托管服务，分布式版本控制系统使用起来方便容易。数百万个非常棒的开源项目驻扎在github上。所以，如果你有任何问题、建议或反馈，请在评论中告诉我们。谢谢大家！好好享受吧 😃</p><hr>`,44)),n("p",null,[t[4]||(t[4]=o("via: ",-1)),i(e,{href:"http://linoxide.com/usr-mgmt/host-open-source-code-repository-github/"},{default:p(()=>[...t[3]||(t[3]=[o("http://linoxide.com/usr-mgmt/host-open-source-code-repository-github/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=o("作者：",-1)),i(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...t[5]||(t[5]=[o("Arun Pyasi",-1)])]),_:1}),t[9]||(t[9]=o(" 译者：",-1)),i(e,{href:"https://github.com/ZTinoZ"},{default:p(()=>[...t[6]||(t[6]=[o("ZTinoZ",-1)])]),_:1}),t[10]||(t[10]=o(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[o("Linux中国",-1)])]),_:1}),t[15]||(t[15]=o(" 荣誉推出",-1))])])}const C=a(d,[["render",u]]);export{w as __pageData,C as default};
